#pragma once
#include "native/Ot.FormWindow.h"
#include "components/Ot.Actions.h"
#include "components/Ot.CategoryTree.h"
#include "components/Ot.TorrentList.h"
#include "Ot.DetailsPane.h"

namespace ot {
// Component inventory, similar to fields generated by the VCL form designer.
class TOtMainFormDesign {
public:
    TOtAction ActionAdd{ID_TASK_ADD};
    TOtAction ActionStart{ID_TASK_START};
    TOtAction ActionPause{ID_TASK_PAUSE};
    TOtAction ActionRecheck{ID_TASK_RECHECK};
    TOtAction ActionRemove{ID_TASK_REMOVE};
    TOtAction ActionAnimate{ID_DEMO_ANIMATE};
    TOtAction ActionDetails{ID_VIEW_DETAILS};
    TOtAction ActionAbout{ID_PROTO_ABOUT};
    TOtAction ActionExit{ID_PROTO_EXIT};
    TOtActionList ActionListMain{&ActionAdd, &ActionStart, &ActionPause, &ActionRecheck,
        &ActionRemove, &ActionAnimate, &ActionDetails, &ActionAbout, &ActionExit};
    TOtUiTimer TimerAnimation;
    TOtCategoryTree TreeViewCategories;
    TOtTorrentList ListViewTorrents;
    TOtDetailsPane DetailsPane;
    WTL::CToolBarCtrl ToolBarMain;
    WTL::CStatusBarCtrl StatusBarMain;
    WTL::CSplitterWindow SplitterMain;
    WTL::CHorSplitterWindow SplitterDetails;

    bool Create(TOtFormWindow& window, const TOtTaskController& source);
    void ShowDetails(bool visible);
    void Layout();
    void ApplyDpi(int dpi);
    void InitialBounds();
private:
    TOtFormWindow* window_{};
    WTL::CFont FontUi;
    int dpi_{96};
    int Px(int value) const { return MulDiv(value, dpi_, 96); }
    bool CreateToolbar();
    void ConnectNativeEvents();
};
}
